# Shared libphext 0.6 chain conformance fixtures (see FIXTURES.md in
# libphext-rs / the ports-v06 workspace). Every case: parse the input
# bytes, check chain/member structure and per-scroll digests against
# the manifest, re-serialize byte-identically, and run every fetch.
# Expectations were generated by libphext-rs 0.6.0 itself — no value
# here is hand-computed.
import hashlib
import json
from pathlib import Path

import pytest

from phext import binary, chain

FIXTURES = Path(__file__).parent / "fixtures" / "chains"


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _cases():
    manifest = json.loads((FIXTURES / "manifest.json").read_text(encoding="utf-8"))
    return manifest["cases"]


@pytest.mark.parametrize("case", _cases(), ids=[c["case"] for c in _cases()])
def test_chain_fixture_case(case):
    case_dir = FIXTURES / case["case"]
    data = (case_dir / case["input_file"]).read_bytes()

    # 1. input identity (catches newline-translating reads immediately)
    assert len(data) == case["input_bytes"], case["case"]
    assert _sha(data) == case["input_sha256"], case["case"]

    stream = data.decode("utf-8")
    chains = chain.parse_chains(stream)

    # 2. structure: chains, closed flags, members, scroll enumeration
    assert len(chains) == len(case["chains"]), case["case"]
    for parsed, expected_chain in zip(chains, case["chains"]):
        assert parsed.closed == expected_chain["closed"], case["case"]
        assert len(parsed.members) == len(expected_chain["members"]), case["case"]
        for member, expected_member in zip(parsed.members, expected_chain["members"]):
            member_bytes = member.encode("utf-8")
            assert len(member_bytes) == expected_member["bytes"], case["case"]
            assert _sha(member_bytes) == expected_member["sha256"], case["case"]
            # scroll enumeration via the byte-level walker, whose
            # segmentation is the reference phokenize's (incl. the
            # empty-member entry the text phokenize does not surface)
            scrolls = binary.phokenize_bytes(member_bytes)
            assert len(scrolls) == expected_member["scroll_count"], (
                case["case"], member[:80])
            assert len(scrolls) == len(expected_member["scrolls"]), case["case"]
            for (s_coord, s_bytes), expected_scroll in zip(scrolls, expected_member["scrolls"]):
                assert str(s_coord) == expected_scroll["c"], case["case"]
                assert len(s_bytes) == expected_scroll["b"], case["case"]
                assert _sha(s_bytes) == expected_scroll["s"], case["case"]

    # 3. round-trip: byte-identical, without exception
    assert chain.serialize_chains(chains).encode("utf-8") == data, case["case"]

    # 4. fetches: byte-exact against the expected files
    for i, fetch in enumerate(case["fetches"]):
        expected = (case_dir / fetch["expected_file"]).read_bytes()
        assert len(expected) == fetch["expected_bytes"], (case["case"], i)
        assert _sha(expected) == fetch["expected_sha256"], (case["case"], i)
        result = chains[fetch["chain_index"]].fetch(fetch["address"])
        assert result.encode("utf-8") == expected, (
            case["case"], fetch["address"])
